#!/usr/bin/env python3
# Builds lms/bank/quiz-bank.js from question-bank/data/qa.json (parsed PDF, private) + question-bank/data/verified/*.json
# (verifier output checked against AWS documentation via the AWS MCP). Gate: only verified/corrected questions with at least
# one AWS-documentation fact (with quote) are included; unsupported fact claims are demoted to reasoning.
import json,glob,re,collections
import os,sys
ROOT=os.path.join(os.path.dirname(os.path.abspath(__file__)),'..')
D=os.path.join(ROOT,'question-bank','data')
Q={q['n']:q for q in json.load(open(os.path.join(D,'qa.json')))}
res=[];
for f in sorted(glob.glob(os.path.join(D,'verified','*.json'))): res+=json.load(open(f))
MOD={1:'org-complexity',2:'new-solutions',3:'continuous-improvement',4:'migration-modernization'}
AWS=re.compile(r'^https://(([a-z0-9-]+\.)?(aws\.amazon\.com|amazonaws\.com)/|repost\.aws/knowledge-center/)')
seen_stems=set();bank=[];held=[];cnt=collections.Counter()
for r in res:
    q=Q[r['n']]; v=r['verdict']; cnt[v]+=1
    ans=re.sub(r'[^A-F]','',r['answer'].split('(')[0].upper()) if r.get('answer') else ''
    claims=[dict(c,evidence=[e for e in c.get('evidence',[]) if AWS.match(e.get('url',''))]) for c in r['claims']]  # drop non-official sources (e.g. repost community articles)
    facts=[c for c in claims if c.get('kind')=='fact' and any(AWS.match(e.get('url','')) and e.get('quote') for e in c.get('evidence',[]))]
    reason=None
    if v not in('verified','corrected'): reason=v
    elif not facts: reason='no documented fact with AWS evidence'
    elif any(c.get('kind')=='limitation' for c in claims): reason='unresolved limitation'
    elif v=='corrected' and 'reasoning' in (r.get('notes') or '').lower(): reason='correction rests on reasoning, not documentation'
    elif re.search(r'placeholder|incomplete|sentence fragment|garbled|truncated|mangled|stem is incomplete|missing exhibit',(r.get('notes') or ''),re.I): reason='stem/options defective (see notes)'
    elif not ans or any(a not in [k for k,_ in q['options']] for a in ans): reason='bad answer key'
    elif 'missing exhibit' in (r.get('notes') or '').lower(): reason='missing exhibit'
    if reason: held.append({'n':r['n'],'verdict':v,'reason':reason,'pdf_answer':r['pdf_answer'],'answer':r['answer'],'notes':r.get('notes','')}); continue
    norm=re.sub(r'\W+',' ',q['stem'].lower()).strip()[:200]
    if norm in seen_stems: held.append({'n':r['n'],'verdict':v,'reason':'duplicate of another question','pdf_answer':r['pdf_answer'],'answer':r['answer'],'notes':''}); continue
    seen_stems.add(norm)
    multi=len(ans)>1
    pc=[]
    for c in claims:
        if c.get('kind')=='fact' and c not in facts: c['kind']='reasoning'
        c.setdefault('kind','reasoning'); c.setdefault('text',c.get('claim',''))  # no AWS page seen for this claim: demote
        pc.append({'scope':'summary','kind':c['kind'],'text':c['text'],'evidence':[{'title':e.get('title',''),'heading':e.get('section',''),'quote':e.get('quote',''),'url':e.get('url',''),'accessed':e.get('accessed','2026-10-31'),'applies':c['text']} for e in c.get('evidence',[])]})
    bank.append({'id':f'sapc02-q{r["n"]:03d}','number':len(bank)+1,'topic':r['topic'],'moduleId':MOD[r['domain']],'question':q['stem'],'options':[{'key':k,'text':t} for k,t in q['options']],'answer':ans,'explanation':r['summary'],'reference':facts[0]['evidence'][0]['url'],'images':[],'interactive':None,'verified':2,'imported':True,'auditVerdict':v,'auditLabel':'Verified against AWS documentation' if v=='verified' else 'Corrected against AWS documentation','auditNote':((f"Source PDF answer was {r['pdf_answer']}. " if v=='corrected' else '')+(r.get('notes') or '')[:400]).strip(),'qtype':'multi' if multi else 'mcq','proof':{'accessed':'2026-10-31','claims':pc}})
out={'generatedAt':'2026-10-31','source':'Private question source verified against AWS documentation via the AWS MCP (answers checked against retrieved documentation text)','questions':bank}
open(os.path.join(ROOT,'lms','bank','quiz-bank.js'),'w').write('// Generated by tools/build-bank.py from question-bank/data/verified. Committed and published with the site.\nwindow.SAPC02_QUIZ_PRIVATE = '+json.dumps(out,indent=1,ensure_ascii=False)+';\n')
json.dump(held,open(os.path.join(D,'held-back.json'),'w'),indent=1,ensure_ascii=False)
print(dict(cnt),'bank',len(bank),'held',len(held))
print(dict(collections.Counter(b['moduleId'] for b in bank)))
